-- Tabla: fza_albaranes_lineas

DROP TABLE IF EXISTS `fza_albaranes_lineas`;
CREATE TABLE `fza_albaranes_lineas` (
  `NUMERO_ALB_ALBLIN` varchar(20) NOT NULL,
  `SERIE_ALB_ALBLIN` varchar(20) NOT NULL,
  `LINEA_ALBLIN` varchar(4) NOT NULL,
  `NUMERO_PED_ALBLIN` varchar(20) NULL DEFAULT NULL,
  `SERIE_PED_ALBLIN` varchar(20) NULL DEFAULT NULL,
  `LINEA_PED_ALBLIN` varchar(4) NULL DEFAULT NULL COMMENT 'Línea de origen en fza_pedidos_lineas',
  `CODIGO_ART_ALBLIN` varchar(20) NULL DEFAULT NULL,
  `CODIGO_FAM_ALBLIN` varchar(20) NULL DEFAULT NULL,
  `NOMBRE_FAM_ALBLIN` varchar(200) NULL DEFAULT NULL,
  `DESCRIPCION_ARTICULO_ALBLIN` varchar(100) NULL DEFAULT NULL,
  `TIPO_CANTIDAD_ARTICULO_ALBLIN` varchar(20) NULL DEFAULT 'Uds',
  `CANTIDAD_ALBLIN` decimal(19,6) NULL DEFAULT '1.000000',
  `CODIGO_TAR_ALBLIN` varchar(10) NULL DEFAULT NULL,
  `ESIMP_INCL_TARIFA_ALBLIN` varchar(1) NULL DEFAULT 'S',
  `TIPO_IVA_ARTICULO_ALBLIN` varchar(2) NULL DEFAULT 'N',
  `PORCENTAJE_IVA_ALBLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_VENTA_SIVA_ARTICULO_ALBLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_VENTA_CIVA_ARTICULO_ALBLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `TOTAL_ALBLIN` decimal(19,6) NULL DEFAULT '0.000000',
  `CODIGO_ALMACEN_ALBLIN` varchar(10) NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `ESFACTURADA_ALBLIN` varchar(1) NULL DEFAULT 'N',
  `NUMERO_FAC_ALBLIN` varchar(20) NULL DEFAULT NULL,
  `SERIE_FAC_ALBLIN` varchar(20) NULL DEFAULT NULL,
  `LINEA_FAC_ALBLIN` varchar(4) NULL DEFAULT NULL,
  `CODIGO_UNIDAD_ALBLIN` varchar(50) NULL DEFAULT NULL,
  `LOTE_ALBLIN` varchar(50) NULL DEFAULT NULL,
  `FECHA_CADUCIDAD_ALBLIN` date NULL DEFAULT NULL,
  `DESCRIPCION_VARIACION_ALBLIN` varchar(200) NULL DEFAULT NULL,
  PRIMARY KEY (`NUMERO_ALB_ALBLIN`,`SERIE_ALB_ALBLIN`,`LINEA_ALBLIN`)
);
ALTER TABLE `fza_albaranes_lineas` ADD INDEX `IDX_ALBLIN_ARTICULO` (`CODIGO_ART_ALBLIN`);
ALTER TABLE `fza_albaranes_lineas` ADD INDEX `IDX_ALBLIN_FAC` (`SERIE_FAC_ALBLIN`, `NUMERO_FAC_ALBLIN`);
ALTER TABLE `fza_albaranes_lineas` ADD INDEX `IDX_ALBLIN_PEDIDO` (`SERIE_PED_ALBLIN`, `NUMERO_PED_ALBLIN`, `LINEA_PED_ALBLIN`);


-- Tabla: fza_almacenes

DROP TABLE IF EXISTS `fza_almacenes`;
CREATE TABLE `fza_almacenes` (
  `CODIGO_ALM_ALM` varchar(10) NOT NULL,
  `CODIGO_EMP_ALM` varchar(20) NOT NULL,
  `ESACTIVO_ALM` varchar(1) NULL DEFAULT 'S',
  `NOMBRE_ALM_ALM` varchar(100) NULL DEFAULT NULL,
  `CODIGO_PADRE_ALM` varchar(10) NULL DEFAULT NULL,
  `ESFISICO_ALM` varchar(1) NULL DEFAULT 'S',
  `TIPO_USO_ALM` varchar(20) NULL DEFAULT 'ESTANDAR',
  `DIRECCION_ALM` varchar(200) NULL DEFAULT NULL,
  `POBLACION_ALM` varchar(200) NULL DEFAULT NULL,
  `CODIGO_POSTAL_ALM` varchar(10) NULL DEFAULT NULL,
  `TELEFONO_ALM` varchar(50) NULL DEFAULT NULL,
  `EMAIL_ALM` varchar(100) NULL DEFAULT NULL,
  `CODIGO_CLI_ALM` varchar(20) NULL DEFAULT NULL,
  `DESTINO_ACTUAL_ALM` varchar(10) NULL DEFAULT NULL COMMENT 'Hacia dónde va la mercancía (Pendiente de recibir)',
  `ORIGEN_ACTUAL_ALM` varchar(10) NULL DEFAULT NULL COMMENT 'De dónde viene la mercancía cargada',
  `ORDEN_ALM` int(11) NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  `PROVINCIA_ALM` varchar(200) NULL DEFAULT NULL,
  PRIMARY KEY (`CODIGO_ALM_ALM`)
);
ALTER TABLE `fza_almacenes` ADD INDEX `IDX_ALMACENES_EMP` (`CODIGO_EMP_ALM`, `ESACTIVO_ALM`);
ALTER TABLE `fza_almacenes` ADD INDEX `IDX_CLIENTE_ALM` (`CODIGO_CLI_ALM`);
ALTER TABLE `fza_almacenes` ADD INDEX `IDX_EMPRESA_ALM` (`CODIGO_EMP_ALM`);
ALTER TABLE `fza_almacenes` ADD INDEX `IDX_PADRE_ALM` (`CODIGO_PADRE_ALM`);

