  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_UNIDAD_PDR`,`CODIGO_ALM_PDR`,`SERIE_DOC_PDR`,`NUMERO_DOC_PDR`,`LINEA_PDR`)
);
