-- Tabla: fza_articulos_tarifas

DROP TABLE IF EXISTS `fza_articulos_tarifas`;
CREATE TABLE `fza_articulos_tarifas` (
  `CODIGO_ART_ARTTAR` varchar(20) NOT NULL,
  `CODIGO_UNICO_ARTTAR` int(11) NOT NULL AUTO_INCREMENT,
  `CODIGO_UNIDAD_ARTTAR` varchar(50) NOT NULL DEFAULT '' COMMENT 'fza_articulos_skus',
  `CODIGO_TAR_ARTTAR` varchar(10) NULL DEFAULT NULL,
  `ESACTIVO_ARTTAR` varchar(1) NULL DEFAULT 'S',
  `PRECIO_SALIDA_ARTTAR` decimal(19,6) NULL DEFAULT NULL,
  `PRECIO_FINAL_ARTTAR` decimal(19,6) NULL DEFAULT '0.000000',
  `PRECIO_DTO_ARTTAR` decimal(19,6) NULL DEFAULT NULL,
  `PORCENTAJE_DTO_ARTTAR` decimal(19,6) NULL DEFAULT NULL,
  `PORCENTAJE_MARGEN_ARTTAR` decimal(19,6) NULL DEFAULT NULL,
  `VALOR_MULTIPLO_AJUSTE_ARTTAR` decimal(19,6) NULL DEFAULT NULL,
  `VALOR_MENOS_AJUSTE_ARTTAR` decimal(19,6) NULL DEFAULT NULL,
  `FECHA_DESDE_ARTTAR` date NULL DEFAULT NULL,
  `FECHA_HASTA_ARTTAR` date NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_UNICO_ARTTAR`)
);
ALTER TABLE `fza_articulos_tarifas` ADD INDEX `IDX_ARTTAR_BUSQ_VIGENTE` (`CODIGO_ART_ARTTAR`, `CODIGO_TAR_ARTTAR`, `ESACTIVO_ARTTAR`, `FECHA_DESDE_ARTTAR`);
ALTER TABLE `fza_articulos_tarifas` ADD INDEX `IDX_ARTTAR_VIGENCIA` (`ESACTIVO_ARTTAR`, `FECHA_HASTA_ARTTAR`);
ALTER TABLE `fza_articulos_tarifas` ADD INDEX `IDX_ART_TARIFAS_BUSQUEDA` (`CODIGO_ART_ARTTAR`, `CODIGO_TAR_ARTTAR`);

