-- Tabla: fza_articulos_vinculos

DROP TABLE IF EXISTS `fza_articulos_vinculos`;
CREATE TABLE `fza_articulos_vinculos` (
  `ID_ARTVIN` int(11) NOT NULL AUTO_INCREMENT,
  `CODIGO_ART_PADRE_ARTVIN` varchar(20) NOT NULL,
  `CODIGO_ART_HIJO_ARTVIN` varchar(20) NOT NULL,
  `CANTIDAD_ARTVIN` decimal(10,2) NULL DEFAULT '1.00',
  `ORDEN_VISUAL_ARTVIN` int(11) NULL DEFAULT '1',
  `ESOBLIGATORIO_ARTVIN` char(1) NULL DEFAULT 'S',
  PRIMARY KEY (`ID_ARTVIN`)
);
ALTER TABLE `fza_articulos_vinculos` ADD INDEX `IDX_ARTVIN_HIJO` (`CODIGO_ART_HIJO_ARTVIN`);
ALTER TABLE `fza_articulos_vinculos` ADD INDEX `IDX_ARTVIN_PADRE` (`CODIGO_ART_PADRE_ARTVIN`);

