-- Tabla: fza_caja_vales

DROP TABLE IF EXISTS `fza_caja_vales`;
CREATE TABLE `fza_caja_vales` (
  `CODIGO_VL` varchar(50) NOT NULL COMMENT 'Código de barras identificador',
  `CODIGO_PADRE_VL` varchar(50) NULL DEFAULT NULL COMMENT 'Si este vale es el cambio de otro anterior, aquí va el ID del padre',
  `PIN_SEGURIDAD_VL` varchar(10) NOT NULL DEFAULT '' COMMENT 'Código aleatorio tipo CVV para validar el vale',
  `ESTADO_VL` varchar(15) NOT NULL DEFAULT 'PENDIENTE' COMMENT 'PENDIENTE, REDIMIDO, ANULADO, CADUCADO',
  `IMPORTE_NOMINAL_VL` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'El valor monetario que tiene este vale',
  `FECHA_EMISION_VL` datetime NOT NULL,
  `FECHA_CADUCIDAD_VL` date NULL DEFAULT NULL,
  `CODIGO_EMP_EMI_VL` varchar(20) NOT NULL,
  `CODIGO_ALM_EMI_VL` varchar(10) NOT NULL,
  `CODIGO_CAJA_EMI_VL` varchar(10) NOT NULL,
  `NUMERO_OPERACION_EMI_VL` varchar(20) NOT NULL COMMENT 'ID operación TPV donde se creó',
  `SERIE_FAC_EMI_VL` varchar(20) NULL DEFAULT NULL COMMENT 'Factura de abono o ticket origen',
  `NUMERO_FAC_EMI_VL` varchar(20) NULL DEFAULT NULL,
  `FECHA_REDENCION_VL` datetime NULL DEFAULT NULL,
  `IMPORTE_REDIMIDO_VL` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Suele coincidir con el nominal al ser de uso único',
  `CODIGO_EMP_RED_VL` varchar(20) NULL DEFAULT NULL,
  `CODIGO_ALM_RED_VL` varchar(10) NULL DEFAULT NULL,
  `CODIGO_CAJA_RED_VL` varchar(10) NULL DEFAULT NULL,
  `NUMERO_OPERACION_RED_VL` varchar(20) NULL DEFAULT NULL COMMENT 'ID operación TPV donde se gastó',
  `SERIE_FAC_RED_VL` varchar(20) NULL DEFAULT NULL COMMENT 'Factura o ticket que se pagó con esto',
  `NUMERO_FAC_RED_VL` varchar(20) NULL DEFAULT NULL,
  `CODIGO_CLI_VL` varchar(20) NULL DEFAULT NULL,
  `OBSERVACIONES_VL` varchar(200) NULL DEFAULT NULL,
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_VL`)
);
ALTER TABLE `fza_caja_vales` ADD INDEX `IDX_CADUCIDAD_VL` (`FECHA_CADUCIDAD_VL`);
ALTER TABLE `fza_caja_vales` ADD INDEX `IDX_ESTADO_VL` (`ESTADO_VL`);
ALTER TABLE `fza_caja_vales` ADD INDEX `IDX_PADRE_VL` (`CODIGO_PADRE_VL`);
ALTER TABLE `fza_caja_vales` ADD INDEX `IDX_VALES_EMI_OP` (`CODIGO_EMP_EMI_VL`, `CODIGO_ALM_EMI_VL`, `CODIGO_CAJA_EMI_VL`, `NUMERO_OPERACION_EMI_VL`);
ALTER TABLE `fza_caja_vales` ADD INDEX `IDX_VALES_RED_OP` (`CODIGO_EMP_RED_VL`, `CODIGO_ALM_RED_VL`, `CODIGO_CAJA_RED_VL`, `NUMERO_OPERACION_RED_VL`);

