ALTER TABLE `fza_clientes` ADD INDEX `IDX_NIF_CLIENTE` (`EMAIL_CLI`);
ALTER TABLE `fza_clientes` ADD INDEX `IDX_POBLACION_CLIENTE` (`NIF_CLI`);
ALTER TABLE `fza_clientes` ADD INDEX `IDX_RAZONSOCIAL_CLIENTE` (`RAZON_SOCIAL_CLI`);
ALTER TABLE `fza_clientes` ADD INDEX `IDX_REFERENCIA_CLIENTE` (`REFERENCIA_CLI`);

