--
-- Idempotente: se puede ejecutar varias veces sin efectos secundarios.
-- =============================================================================

UPDATE fza_facturas AS F
   JOIN (
       SELECT NUMERO_FAC_FACLIN,
              SERIE_FAC_FACLIN,
              LPAD(MAX(CAST(LINEA_FACLIN AS UNSIGNED)), 3, ''0'') AS ULTIMA_LINEA
         FROM fza_facturas_lineas
