  `MASTER_FIELDS_INFGUI`    varchar(200) NOT NULL,
  `DETAIL_FIELDS_INFGUI`    varchar(200) NOT NULL,

  `ORDEN_INFGUI`            int(11)      NOT NULL DEFAULT 0,
  `ESACTIVO_INFGUI`         varchar(1)   NOT NULL DEFAULT ''S'',

  `INSTANTE_ALTA`           datetime     NOT NULL,
