  ('242', 'compras_sesiones_temporada_fotos', '-- ============================================================================
-- Compras / sesiones — promocion definitiva (extras)
--
--   1. Cabecera fza_compras_sesiones: nueva columna ID_PV_TEMPORADA_SES
--      (FK logica a fza_propiedades_valores con ID_PROP_PV=''TEMPORADA'').
--      Una unica temporada por sesion. Se propaga a fza_articulos_propiedades
--      con CODIGO_PROP_ARTPROP=''TEMPORADA'' durante la materializacion.
--
--   2. Tabla fza_compras_sesiones_fotos — fotos por linea de sesion antes
--      de materializar el articulo. El usuario captura fotos en muestrario
--      contra (SERIE, NUMERO, LINEA[, CODIGO_UNIDAD]); al materializar
--      pasan a fza_articulos_fotos con CODIGO_ART = CODIGO_ART_REUSAR o
--      CODIGO_ART_TENTATIVO resuelto. Diseno alineado con
--      DESARROLLOS EN CURSO/fotos_sesiones.md.
--
-- Todo idempotente: pasa por INFORMATION_SCHEMA antes de aplicar.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Columna ID_PV_TEMPORADA_SES en cabecera
-- ---------------------------------------------------------------------------
SET @col_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_compras_sesiones''
     AND COLUMN_NAME  = ''ID_PV_TEMPORADA_SES''
);
SET @ddl := IF(@col_exists = 0,
  ''ALTER TABLE `fza_compras_sesiones` ''
  ''ADD COLUMN `ID_PV_TEMPORADA_SES` int(11) NULL DEFAULT NULL ''
  ''  COMMENT ''''FK logica fza_propiedades_valores.ID_PV_ARTPROP con ''
  ''ID_PROP_PV=TEMPORADA. Una unica temporada por sesion; se propaga a ''
  ''cada articulo creado en fza_articulos_propiedades.'''''',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_compras_sesiones''
     AND INDEX_NAME   = ''IDX_SES_TEMPORADA''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_compras_sesiones` ''
  ''ADD INDEX `IDX_SES_TEMPORADA` (`ID_PV_TEMPORADA_SES`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

-- ---------------------------------------------------------------------------
-- 2. Tabla fza_compras_sesiones_fotos
-- ---------------------------------------------------------------------------
-- Una fila por foto subida en sesion. CODIGO_UNIDAD_CSF='''' = foto a nivel
-- de la linea (articulo "padre"); != '''' = foto a nivel de SKU (o prefijo).
-- CODIGO_ART_TENTATIVO_CSF se guarda redundantemente para trazabilidad si
-- el codigo tentativo cambia (raro).
SET @tab_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.TABLES
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_compras_sesiones_fotos''
);
SET @ddl := IF(@tab_exists = 0,
  ''CREATE TABLE `fza_compras_sesiones_fotos` (''
  ''  `SERIE_SES_CSF`            varchar(12)  NOT NULL,''
  ''  `NUMERO_SES_CSF`           varchar(12)  NOT NULL,''
  ''  `LINEA_CSF`                int(11)      NOT NULL,''
  ''  `CODIGO_UNIDAD_CSF`        varchar(50)  NOT NULL DEFAULT '''''''',''
  ''  `CODIGO_ART_TENTATIVO_CSF` varchar(20)  NOT NULL,''
  ''  `NOMBRE_FOT_CSF`           varchar(255) NOT NULL,''
  ''  `EXTENSION_ORIGEN_CSF`     varchar(10)  NOT NULL DEFAULT ''''png'''',''
  ''  `INSTANTE_MODIF`           timestamp    NOT NULL ''
  ''       DEFAULT current_timestamp() ON UPDATE current_timestamp(),''
  ''  `INSTANTE_ALTA`            timestamp    NOT NULL ''
  ''       DEFAULT ''''0000-00-00 00:00:00'''',''
  ''  `USUARIO_ALTA`             varchar(100) NOT NULL,''
  ''  `USUARIO_MODIF`            varchar(100) NOT NULL,''
  ''  PRIMARY KEY (`SERIE_SES_CSF`,`NUMERO_SES_CSF`,''
  ''               `LINEA_CSF`,`CODIGO_UNIDAD_CSF`)''
  '')'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_compras_sesiones_fotos''
     AND INDEX_NAME   = ''IDX_CSF_LIN''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_compras_sesiones_fotos` ''
  ''ADD INDEX `IDX_CSF_LIN` ''
  ''(`SERIE_SES_CSF`,`NUMERO_SES_CSF`,`LINEA_CSF`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;

SET @idx_exists := (
  SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS
   WHERE TABLE_SCHEMA = DATABASE()
     AND TABLE_NAME   = ''fza_compras_sesiones_fotos''
     AND INDEX_NAME   = ''IDX_CSF_TENT''
);
SET @ddl := IF(@idx_exists = 0,
  ''ALTER TABLE `fza_compras_sesiones_fotos` ''
  ''ADD INDEX `IDX_CSF_TENT` (`CODIGO_ART_TENTATIVO_CSF`)'',
  ''SELECT 1'');
PREPARE stmt FROM @ddl;
EXECUTE stmt;
DEALLOCATE PREPARE stmt;
', '2026-05-22 00:16:41', '2026-05-22 00:16:41', 'Administrador', 'Administrador'),
  ('243', 'compras_sesiones_definitivo', '-- ============================================================================
-- Sesiones de compra — promocion del form de "prueba" a definitivo
--
-- El form inMtoPruebaSesionGrid / TfrmMtoPruebaSesionGrid + winform
-- "PruebaSesionGrid" pasa a ser el Mto definitivo de Sesiones de compra:
--
--   - Unit:   inMtoComprasSesiones  (ubicado en src/Forms/)
--   - Clase:  TfrmMtoComprasSesiones
--   - Winform:CALL_WINF = ''ComprasSesiones''
--
-- Este script reescribe la entrada de fza_winforms para reflejar los
-- nombres nuevos. Idempotente: INSERT del nuevo + DELETE del antiguo,
-- ambos pasos envueltos en checks de existencia.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- 1. Alta del nuevo CALL_WINF = ''ComprasSesiones''
-- ---------------------------------------------------------------------------
INSERT INTO `fza_winforms`
  (`CALL_WINF`, `CAPTION_WINF`, `MENUITEM_WINF`,
   `UNITF_WINF`, `SHORTCUT_WINF`, `DATAMODULE_WINF`, `NUM_VENTANAS_WINF`)
VALUES
  (''ComprasSesiones'',
   ''Crear articulos y un pedido o un albaran'',
   NULL,
   ''inMtoComprasSesiones.TfrmMtoComprasSesiones'',
   ''Ctrl+Shift+S'',
   ''UniDataComprasSesiones.TdmComprasSesiones'',
   1)
ON DUPLICATE KEY UPDATE
  `CAPTION_WINF`     = VALUES(`CAPTION_WINF`),
  `UNITF_WINF`       = VALUES(`UNITF_WINF`),
  `SHORTCUT_WINF`    = VALUES(`SHORTCUT_WINF`),
  `DATAMODULE_WINF`  = VALUES(`DATAMODULE_WINF`),
  `NUM_VENTANAS_WINF`= VALUES(`NUM_VENTANAS_WINF`);

-- ---------------------------------------------------------------------------
-- 2. Baja del antiguo CALL_WINF = ''PruebaSesionGrid'' (si todavia existe)
-- ---------------------------------------------------------------------------
DELETE FROM `fza_winforms`
 WHERE `CALL_WINF` = ''PruebaSesionGrid'';
', '2026-05-22 00:16:46', '2026-05-22 00:16:46', 'Administrador', 'Administrador'),
  ('244', 'compras_sesiones_fix_reusar', '-- ============================================================================
-- Compras / sesiones — auto-resolver duplicados como REUSAR
--
-- Para sesiones en BORRADOR cuyas lineas tienen ESDUPLICADO_SESLIN=''S''
-- (codigo de articulo tentativo coincide con un fza_articulos existente)
-- pero no tienen ACCION_DUPLICADO_SESLIN resuelta, marcamos REUSAR por
-- defecto apuntando al articulo existente.
--
-- Es lo que hace ahora el BeforePost del Mto para lineas nuevas; este
-- script es la migracion para datos ya grabados antes del fix.
--
-- Es seguro re-ejecutarlo: solo actua sobre lineas con accion vacia.
-- Solo toca sesiones en BORRADOR (las CERRADA / ANULADA no se tocan).
-- ============================================================================

UPDATE `fza_compras_sesiones_lineas` L
  JOIN `fza_compras_sesiones`   S
    ON S.`SERIE_SES`  = L.`SERIE_SES_SESLIN`
   AND S.`NUMERO_SES` = L.`NUMERO_SES_SESLIN`
  JOIN `fza_articulos`          A
    ON A.`CODIGO_ART_ART` = L.`CODIGO_ART_TENTATIVO_SESLIN`
   AND A.`ESACTIVO_ART`   = ''S''
   SET L.`ACCION_DUPLICADO_SESLIN`  = ''REUSAR'',
       L.`CODIGO_ART_REUSAR_SESLIN` = L.`CODIGO_ART_TENTATIVO_SESLIN`,
       L.`ESDUPLICADO_SESLIN`       = ''S'',
       L.`INSTANTE_MODIF`           = NOW(),
       L.`USUARIO_MODIF`            = COALESCE(L.`USUARIO_MODIF`,
                                                ''Administrador'')
 WHERE S.`ESTADO_SES` = ''BORRADOR''
   AND L.`ESDUPLICADO_SESLIN`       = ''S''
   AND (L.`ACCION_DUPLICADO_SESLIN` IS NULL
        OR TRIM(L.`ACCION_DUPLICADO_SESLIN`) = '''');
', '2026-05-22 00:28:16', '2026-05-22 00:28:16', 'Administrador', 'Administrador'),
  ('245', NULL, 'ALTER TABLE fza_usuarios_perfiles MODIFY COLUMN VALUE_BLOB_USUPER MEDIUMBLOB;', '2026-05-22 18:07:45', '2026-05-22 18:07:45', 'Administrador', 'Administrador'),
  ('246', 'fix_contador_lineas_ses', '-- =============================================================================
-- Fix CONTADOR_LINEAS_SES en fza_compras_sesiones
-- =============================================================================
-- Sincroniza el contador de lineas de la cabecera con la ultima LINEA real
-- almacenada en fza_compras_sesiones_lineas. Repara sesiones donde el
-- contador quedo por debajo del MAX(LINEA_SESLIN) por desync master/detail.
--
-- Caso clasico que dejaba el contador colgado:
--   1. Master cargado con CONTADOR=110, max LINEA=110.
--   2. Add -> AfterInsert pone CONTADOR=120 (memoria) y LINEA=120 (memoria).
--   3. Navegacion -> detail.Post implicito persiste LINEA=120 en BD.
--   4. Usuario cancela el master -> CONTADOR rollback a 110 (BD), pero
--      linea 120 sigue persistida.
--   5. Siguiente Add reasignaba CONTADOR+10=120 -> colision con PK
--      (SERIE_SES_SESLIN, NUMERO_SES_SESLIN, LINEA_SESLIN).
--
-- El nuevo helper inLibContadorLineas.GetSiguienteLineaDoc hace el UPDATE
-- atomico contra BD, asi que el problema no puede repetirse para nuevas
-- sesiones. Este script repara las que ya quedaron con el contador
-- desincronizado en su momento.
--
-- Idempotente: se puede ejecutar varias veces sin efectos secundarios.
-- =============================================================================

UPDATE fza_compras_sesiones AS S
   JOIN (
       SELECT SERIE_SES_SESLIN,
              NUMERO_SES_SESLIN,
              MAX(LINEA_SESLIN) AS ULTIMA_LINEA
         FROM fza_compras_sesiones_lineas
        GROUP BY SERIE_SES_SESLIN, NUMERO_SES_SESLIN
   ) AS L
     ON L.SERIE_SES_SESLIN  = S.SERIE_SES
    AND L.NUMERO_SES_SESLIN = S.NUMERO_SES
  SET S.CONTADOR_LINEAS_SES = L.ULTIMA_LINEA
WHERE S.CONTADOR_LINEAS_SES IS NULL
   OR S.CONTADOR_LINEAS_SES < L.ULTIMA_LINEA;
