 WHERE (NUMERO_ALBC_ALBCLIN, SERIE_ALBC_ALBCLIN) IN (
   SELECT NUMERO_ALBC_SES, SERIE_ALBC_SES FROM fza_compras_sesiones
    WHERE SERIE_SES = ''A1'' AND NUMERO_SES = ''000002''
