-- Tabla: fza_inventarios_lineas

DROP TABLE IF EXISTS `fza_inventarios_lineas`;
CREATE TABLE `fza_inventarios_lineas` (
  `CODIGO_EMP_INVLIN` varchar(10) NOT NULL,
  `CODIGO_ALM_INVLIN` varchar(10) NOT NULL,
  `SERIE_INV_INVLIN` varchar(20) NOT NULL,
  `NUMERO_INV_INVLIN` varchar(20) NOT NULL,
  `LINEA_INVLIN` varchar(8) NOT NULL COMMENT 'Secuencial de la línea (00000001, 00000002...)',
  `CODIGO_ART_INVLIN` varchar(20) NOT NULL,
  `CODIGO_UNIDAD_INVLIN` varchar(50) NOT NULL COMMENT 'El SKU específico contado',
  `LOTE_INVLIN` varchar(50) NULL DEFAULT '',
  `FECHA_CADUCIDAD_INVLIN` date NULL DEFAULT NULL,
  `DESCRIPCION_ARTICULO_INVLIN` varchar(200) NULL DEFAULT NULL,
  `CANTIDAD_TEORICA_INVLIN` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Stock actual en sistema',
  `CANTIDAD_FISICA_INVLIN` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Stock contado',
  `CANTIDAD_DIFERENCIA_INVLIN` decimal(19,6) NOT NULL DEFAULT '0.000000' COMMENT 'Física - Teórica',
  `PRECIO_MEDIO_INVLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'PMP que tenía el sistema antes del inventario',
  `PRECIO_MEDIO_NUEVO_INVLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'PMP corregido por el usuario (apreciación/depreciación)',
  `TOTAL_COSTE_DIFERENCIA_INVLIN` decimal(19,6) NULL DEFAULT '0.000000' COMMENT 'Fórmula sugerida: (CANTIDAD_FISICA * PRECIO_MEDIO_NUEVO) - (CANTIDAD_TEORICA * PRECIO_MEDIO_ACTUAL)',
  `FECHA_RECUENTO_INVLIN` datetime NULL DEFAULT NULL COMMENT 'Instante exacto del escaneo',
  `INSTANTE_MODIF` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE CURRENT_TIMESTAMP,
  `INSTANTE_ALTA` timestamp NOT NULL DEFAULT '0000-00-00 00:00:00',
  `USUARIO_ALTA` varchar(100) NOT NULL,
  `USUARIO_MODIF` varchar(100) NOT NULL,
  PRIMARY KEY (`CODIGO_EMP_INVLIN`,`CODIGO_ALM_INVLIN`,`SERIE_INV_INVLIN`,`NUMERO_INV_INVLIN`,`LINEA_INVLIN`)
);
ALTER TABLE `fza_inventarios_lineas` ADD INDEX `IDX_INV_LIN_ARTICULO` (`CODIGO_ART_INVLIN`);
ALTER TABLE `fza_inventarios_lineas` ADD INDEX `IDX_INV_LIN_UNIDAD` (`CODIGO_UNIDAD_INVLIN`);

