DROP TABLE IF EXISTS `fza_valores_defecto`;
CREATE TABLE `fza_valores_defecto` (
  `TABLA_OBJETIVO_DEF_VD` varchar(60) NOT NULL COMMENT 'Nombre de la tabla, ej: fza_articulos',
  `CAMPO_OBJETIVO_DEF_VD` varchar(60) NOT NULL COMMENT 'Nombre del campo, ej: TIPO_IVA_ART',
  `VALOR_DEF_VD` varchar(255) NULL DEFAULT NULL COMMENT 'El valor fijo a insertar',
  `TIPO_DATO_DEF_VD` varchar(20) NULL DEFAULT 'STRING' COMMENT 'STRING, INTEGER, FLOAT, BOOLEAN, MACRO',
  `DESCRIPCION_DEF_VD` varchar(100) NULL DEFAULT NULL COMMENT 'Para que sepas qué es esto',
  `VALORES_POSIBLES_DEF_VD` varchar(500) NULL DEFAULT NULL COMMENT 'Lista separada por comas (ej: S,N o 21,10,4)',
  PRIMARY KEY (`TABLA_OBJETIVO_DEF_VD`,`CAMPO_OBJETIVO_DEF_VD`)
);

