CREATE ALGORITHM=UNDEFINED  VIEW `vi_proveedores` AS select `fza_proveedores`.`CODIGO_PRV_PRV` AS `CODIGO_PRV_PRV`,`fza_proveedores`.`ESACTIVO_PRV` AS `ESACTIVO_PRV`,`fza_proveedores`.`RAZON_SOCIAL_PRV` AS `RAZON_SOCIAL_PRV`,`fza_proveedores`.`NIF_PRV` AS `NIF_PRV`,`fza_proveedores`.`MOVIL_PRV` AS `MOVIL_PRV`,`fza_proveedores`.`EMAIL_PRV` AS `EMAIL_PRV`,`fza_proveedores`.`DIRECCION1_PRV` AS `DIRECCION1_PRV`,`fza_proveedores`.`DIRECCION2_PRV` AS `DIRECCION2_PRV`,`fza_proveedores`.`POBLACION_PRV` AS `POBLACION_PRV`,`fza_proveedores`.`PROVINCIA_PRV` AS `PROVINCIA_PRV`,`fza_proveedores`.`CODIGO_POSTAL_PRV` AS `CODIGO_POSTAL_PRV`,`fza_proveedores`.`PAIS_PRV` AS `PAIS_PRV`,`fza_proveedores`.`OBSERVACIONES_PRV` AS `OBSERVACIONES_PRV`,`fza_proveedores`.`REFERENCIA_PRV` AS `REFERENCIA_PRV`,`fza_proveedores`.`CONTACTO_PRV` AS `CONTACTO_PRV`,`fza_proveedores`.`TELEFONO_CONTACTO_PRV` AS `TELEFONO_CONTACTO_PRV`,`fza_proveedores`.`TELEFONO_PRV` AS `TELEFONO_PRV`,`fza_proveedores`.`IBAN_PRV` AS `IBAN_PRV`,`fza_proveedores`.`ORDEN_PRV` AS `ORDEN_PRV`,`fza_proveedores`.`INSTANTE_MODIF` AS `INSTANTE_MODIF`,`fza_proveedores`.`INSTANTE_ALTA` AS `INSTANTE_ALTA`,`fza_proveedores`.`USUARIO_ALTA` AS `USUARIO_ALTA`,`fza_proveedores`.`USUARIO_MODIF` AS `USUARIO_MODIF` from `fza_proveedores`;

